class AddressLayerProtocol(typing.Protocol):
    """
    An opened `.address.ptiles` file. Separate from `PtilesLayer` because
    address uses a v2 merged-block index, not the v1 block reader.
    """

    def addresses_at(self, lat: "float",lon: "float",ring: "int"):
        """
        Reverse lookup: all addresses in the cell(s) covering `(lat, lon)`
        (`ring == 1` adds neighbors).
        """

        raise NotImplementedError
    def find_address(self, lat: "float",lon: "float",ring: "int",housenumber: "str",street: "str"):
        """
        Forward lookup: addresses near `(lat, lon)` matching `housenumber` +
        `street` (accent/case-insensitive).
        """

        raise NotImplementedError
# AddressLayer is a Rust-only trait - it's a wrapper around a Rust implementation.
class AddressLayer():
    """
    An opened `.address.ptiles` file. Separate from `PtilesLayer` because
    address uses a v2 merged-block index, not the v1 block reader.
    """

    _pointer: ctypes.c_void_p
    
    def __init__(self, *args, **kwargs):
        raise ValueError("This class has no default constructor")

    def __del__(self):
        # In case of partial initialization of instances.
        pointer = getattr(self, "_pointer", None)
        if pointer is not None:
            _uniffi_rust_call(_UniffiLib.uniffi_ptiles_ffi_fn_free_addresslayer, pointer)

    def _uniffi_clone_pointer(self):
        return _uniffi_rust_call(_UniffiLib.uniffi_ptiles_ffi_fn_clone_addresslayer, self._pointer)

    # Used by alternative constructors or any methods which return this type.
    @classmethod
    def _make_instance_(cls, pointer):
        # Lightly yucky way to bypass the usual __init__ logic
        # and just create a new instance with the required pointer.
        inst = cls.__new__(cls)
        inst._pointer = pointer
        return inst
    @classmethod
    def open(cls, path: "str"):
        """
        Open an address file, local path or `http(s)://` URL.
        """

